export const SPELLS = {};
for (const [id, name, level, sc, time, range, comp, dur, flags, cls, desc] of RAW) {
  SPELLS[id] = {
    id, name, level, school: SCHOOL[sc], time: TIME[time] || time, range, comp, dur,
    conc: flags.includes('c'), ritual: flags.includes('r'), classes: [...cls].map((c) => SPELL_CLASS_KEYS[c]), desc,
  };
}
// Усі закляття: за колом, потім за назвою
export const SPELL_IDS = Object.keys(SPELLS).sort((a, b) => SPELLS[a].level - SPELLS[b].level || SPELLS[a].name.localeCompare(SPELLS[b].name, 'uk'));

// Тривалість для показу (з концентрацією)
export const spellDuration = (sp) => (sp.conc ? `Концентрація, до ${sp.dur}` : sp.dur);

